#!/usr/bin/env bash
# The lifecycle skills in .agents/skills/ are generated by `openspec update`, never hand-written.
# This regenerates them and fails when the result differs from the committed tree, so a hand edit or
# a stale copy is caught instead of merged.
#
# `openspec update` renders its workflow set from the OpenSpec GLOBAL profile, which is per machine
# (a fresh CI runner defaults to `core`). The set this repo wants is pinned in
# openspec/cli-config.json and injected through XDG_CONFIG_HOME, so the check is reproducible
# everywhere. To change the set, edit that file and run `openspec update`.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "${SCRIPT_DIR}/.."

if ! command -v openspec >/dev/null 2>&1; then
  echo "check-openspec-skills: the openspec CLI is required; install the pinned version with: npm install -g @fission-ai/openspec@1.14.0" >&2
  exit 1
fi

scratch="$(mktemp -d)"
trap 'rm -rf "${scratch}"' EXIT
mkdir -p "${scratch}/openspec"
cp openspec/cli-config.json "${scratch}/openspec/config.json"

XDG_CONFIG_HOME="${scratch}" openspec update >/dev/null

if ! git diff --exit-code -- .agents/skills; then
  echo "check-openspec-skills: .agents/skills/ drifted from what \`openspec update\` generates." >&2
  echo "Regenerate and commit the result (CONTRIBUTING.md, 'The OpenSpec workflow > Skills')." >&2
  exit 1
fi
